import { HStack, Text, VStack } from '@advui/core'
import { VirtualList } from '@advui/data'

const clients = ['Shwe Taung', 'Golden Lotus', 'Irrawaddy Trading', 'Mandalay Print', 'Yoma Foods']

const invoices = Array.from({ length: 10_000 }, (_, i) => ({
  id: `INV-${String(i + 1).padStart(5, '0')}`,
  client: clients[i % clients.length]!,
  amount: ((i * 7919) % 90_000) / 100 + 100,
}))

export default function VirtualListBasic() {
  return (
    <VirtualList
      aria-label="Invoices"
      height="80"
      width="100%"
      maxWidth="112"
      borderWidth={1}
      borderColor="border"
      borderRadius="lg"
      data={invoices}
      itemHeight={56}
      getItemKey={(invoice) => invoice.id}
      renderItem={(invoice) => (
        <HStack
          height="100%"
          alignItems="center"
          justifyContent="space-between"
          gap="3"
          paddingHorizontal="4"
          borderBottomWidth={1}
          borderColor="border"
        >
          <VStack flexShrink={1}>
            <Text size="sm" weight="medium">
              {invoice.id}
            </Text>
            <Text size="xs" tone="muted" truncate>
              {invoice.client}
            </Text>
          </VStack>
          <Text size="sm">${invoice.amount.toFixed(2)}</Text>
        </HStack>
      )}
    />
  )
}

import { HStack, Spinner, Text } from '@advui/core'
import { VirtualList } from '@advui/data'
import { useEffect, useRef, useState } from 'react'

const pageSize = 30
const lastPage = 5

const page = (n: number) =>
  Array.from({ length: pageSize }, (_, i) => {
    const index = n * pageSize + i
    return { id: index, text: `Order ${String(4800 - index).padStart(4, '0')} shipped` }
  })

export default function VirtualListLoadMore() {
  const [orders, setOrders] = useState(() => page(0))
  const [loading, setLoading] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined)
  useEffect(() => () => clearTimeout(timer.current), [])

  const done = orders.length >= pageSize * lastPage
  const loadMore = () => {
    if (loading || done) return
    setLoading(true)
    // Stands in for a request to your API.
    timer.current = setTimeout(() => {
      setOrders((current) => [...current, ...page(current.length / pageSize)])
      setLoading(false)
    }, 800)
  }

  return (
    <VirtualList
      aria-label="Shipped orders"
      aria-busy={loading}
      height="80"
      width="100%"
      maxWidth="96"
      borderWidth={1}
      borderColor="border"
      borderRadius="lg"
      data={orders}
      itemHeight={44}
      getItemKey={(order) => order.id}
      onEndReached={loadMore}
      renderItem={(order) => (
        <HStack height="100%" alignItems="center" paddingHorizontal="4">
          <Text size="sm">{order.text}</Text>
        </HStack>
      )}
      footer={
        // A set height, so the list does not jump when the spinner shows.
        <HStack justifyContent="center" alignItems="center" gap="2" height="12">
          {loading ? <Spinner size="sm" aria-hidden /> : null}
          {loading || done ? (
            <Text size="sm" tone="muted">
              {loading ? 'Loading more orders…' : 'All 150 orders'}
            </Text>
          ) : null}
        </HStack>
      }
    />
  )
}

import { HStack, Text, VStack } from '@advui/core'
import { VirtualList } from '@advui/data'

type Row =
  | { kind: 'day'; id: string; label: string }
  | { kind: 'message'; id: string; from: string; text: string }

const people = ['Thiri', 'Kyaw Zin', 'May', 'Htet']
const notes = [
  'Sent the township figures.',
  'The Bago sheet needs one more column.',
  'Can we move the review to Thursday?',
  'Uploaded the new map.',
]

// Each day: a heading, then six messages.
const rows: Row[] = Array.from({ length: 60 }, (_, day) => [
  { kind: 'day' as const, id: `day-${day}`, label: `October ${(day % 30) + 1}` },
  ...Array.from({ length: 6 }, (_, i) => ({
    kind: 'message' as const,
    id: `m-${day}-${i}`,
    from: people[(day + i) % people.length]!,
    text: notes[(day * 3 + i) % notes.length]!,
  })),
]).flat()

export default function VirtualListVariableHeights() {
  return (
    <VirtualList
      aria-label="Messages"
      height="80"
      width="100%"
      maxWidth="96"
      borderWidth={1}
      borderColor="border"
      borderRadius="lg"
      data={rows}
      itemHeight={(index) => (rows[index]!.kind === 'day' ? 32 : 60)}
      getItemKey={(row) => row.id}
      renderItem={(row) =>
        row.kind === 'day' ? (
          <HStack height="100%" alignItems="center" paddingHorizontal="4" backgroundColor="muted">
            <Text size="xs" weight="semibold" tone="muted">
              {row.label}
            </Text>
          </HStack>
        ) : (
          <VStack height="100%" justifyContent="center" paddingHorizontal="4">
            <Text size="sm" weight="medium">
              {row.from}
            </Text>
            <Text size="sm" tone="muted" truncate>
              {row.text}
            </Text>
          </VStack>
        )
      }
    />
  )
}
